const wf={page:'dash',task:null,tab:'过程',filter:'全部',query:'',hot:'榜单',seq:300,defaults:{budget:20},events:[],notifications:[],records:[],sources:[
 ['newsnow','newsnow / DailyHotApi','热榜接口','平台榜单与排名'],['search','Bocha / Tavily / Anspire','检索服务','新闻与网页链接'],['fetch','Firecrawl / Jina','正文服务','原文抽取与归档'],['crawler','MediaCrawler','平台采集','获授权的帖子与评论'],['db','研判数据库','本地存储','已归档内容与证据']
 ],monitors:[{id:'MON-01',name:'AI 行业动态',keywords:'人工智能,大模型,AI',frequency:'15 分钟',strategy:'创建待确认任务',channel:'仅平台内',enabled:true},{id:'MON-02',name:'品牌安全值守',keywords:'产品安全,投诉',frequency:'30 分钟',strategy:'自动研判',channel:'飞书',enabled:true}],signals:[{id:'SIG-01',title:'AI 行业讨论出现新线索',reason:'演示：关键词命中、满足观察窗口；实际阈值由规则配置。',monitor:'MON-01',status:'待关注',task:null},{id:'SIG-02',title:'品牌产品安全线索待核实',reason:'演示：命中安全主题；风险线索不代表指控成立。',monitor:'MON-02',status:'研究中',task:'TASK-201'}],notify:{channel:'仅平台内',budget:80,quiet:'22:00–08:00'},pending:null};
const wfClone=x=>JSON.parse(JSON.stringify(x));
function wfNow(){return new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,16);}
const wfTasks=rcRows.map(r=>({id:r.task,title:r.title,source:r.type==='日报'?'定时任务':'对话',status:r.status==='待审核'?'待审核':'完成',stage:8,created:r.date,window:'原报告时间窗',template:r.type,budget:20,parent:null,report:r.id,attempt:1,notes:[],evidence:r.id==='ai'?wfClone(v4Research.evidence):[],claims:r.id==='ai'?wfClone(v4Research.claims):[],config:'原报告示例配置',events:[{time:r.date,text:'历史演示任务，保留原报告关联；未执行真实调用。'}]}));
wfTasks.unshift({id:'TASK-201',title:'品牌产品安全线索调查',source:'热点自动触发',status:'运行中',stage:1,created:'2026-10-17 16:00',window:'近 7 天',template:'危机事件分析',budget:20,parent:null,report:null,attempt:1,notes:[],evidence:[],claims:[],config:'CFG-DEMO-01',events:[{time:'2026-10-17 16:00',text:'自动监测示例已进入执行槽，未调用真实引擎。'}]});
wfTasks.unshift({id:'TASK-202',title:'新能源汽车行业舆情研究',source:'对话',status:'排队中',stage:0,created:'2026-10-17 16:05',window:'近 7 天',template:'行业动态分析',budget:20,parent:null,report:null,attempt:1,notes:[],evidence:[],claims:[],config:'CFG-DEMO-01',events:[{time:'2026-10-17 16:05',text:'等待执行槽；不会覆盖其他任务。'}]});
wfTasks.unshift({id:'TASK-203',title:'补充研究：平台争议原始材料',source:'对话',status:'等待审批',stage:1,created:'2026-10-17 16:10',window:'近 7 天',template:'事件分析',budget:20,parent:'TASK-101',report:null,attempt:1,notes:[],evidence:[],claims:[],config:'CFG-DEMO-01',events:[{time:'2026-10-17 16:10',text:'示例需要扩大登录态采集范围，等待单独授权。'}]});
const wfTask=id=>wfTasks.find(t=>t.id===id);
const wfSafe=v4Esc;
function wfBadge(s){const c=['完成','可交付'].includes(s)?'good':['运行中','研究中'].includes(s)?'blue':['失败','已取消'].includes(s)?'red':['待关注','等待审批','待审核','待确认'].includes(s)?'amber':'';return `<span class="wf-badge ${c}">${wfSafe(s)}</span>`;}
function wfEvent(t,text){t.events.push({time:wfNow(),text});}
function wfNote(kind,t,title){const key=kind+':'+t.id+':'+t.attempt;if(wf.notifications.some(n=>n.key===key))return;wf.notifications.unshift({key,task:t.id,title,channel:kind==='complete'&&rcState.subscription&&(rcState.subscription.type==='全部'||rcState.subscription.type===rcRows.find(r=>r.task===t.id)?.type)?rcState.subscription.channel:(t.channel||wf.notify.channel),time:wfNow(),status:'待接入 · 未发送'});}
function wfDispatch(){if(wfTasks.some(t=>t.status==='运行中'))return;const next=wfTasks.filter(t=>t.status==='排队中').sort((a,b)=>(a.source==='对话'?0:1)-(b.source==='对话'?0:1)||a.created.localeCompare(b.created)||(a.order||0)-(b.order||0))[0];if(next){next.status='运行中';wfEvent(next,'获得演示执行槽；配置快照已固定。');}}
function wfCreate(title,source='对话',options={}){const t={id:'TASK-'+(++wf.seq),title,source,status:options.draft?'待确认':'排队中',stage:0,created:wfNow(),window:/30天|30 天|一个月/.test(title)?'近 30 天':/24小时|24 小时|今天/.test(title)?'近 24 小时':'近 7 天',template:/竞争|竞品/.test(title)?'市场竞争格局':/政策|行业/.test(title)?'政策或行业动态':/品牌/.test(title)?'企业品牌声誉':/危机|安全|投诉/.test(title)?'突发事件与危机公关':/日报|周报/.test(title)?'定期监测':'公共事件分析',order:wf.seq,budget:Number(title.match(/预算(?:上限)?[为是：:\s¥￥]*([0-9]+(?:\.[0-9]+)?)/)?.[1])||wf.defaults.budget,parent:options.parent||null,report:null,attempt:1,notes:[],evidence:[],claims:[],channel:options.channel||wf.notify.channel,config:{model:v4State.model,slots:wfClone(v4Slots),services:wfClone(v4Services),budget:wf.defaults.budget},events:[]};wfTasks.unshift(t);wfEvent(t,'已建立独立本地任务；默认真实资料与完整报告要求，缺失不补造。');t.config.budget=t.budget;if(source==='对话'&&v4Session().signal){const sig=wf.signals.find(x=>x.id===v4Session().signal);if(sig){sig.task=t.id;sig.status='研究中';}}if(!options.draft)wfDispatch();return t;}
function wfIntent(q){if(/这份报告|报告中|报告里|报告的/.test(q)&&!/重新|补充|再查|调查|新.*研究/.test(q))return false;return !/什么是|是什么|什么意思|如何使用|怎么用|怎么配置|流程是什么|能不能|可以吗|有什么区别|为什么/.test(q)&&/(研究|调查|研判|分析|帮我查|查一下|生成.*报告|出.*报告|出报)/.test(q);}
const wfBasicAnswer=v4Answer;
const wfOriginalMessageHTML=v4MessageHTML;
v4Send=function(q){q=q.trim();if(!q)return;const s=v4Session();s.messages.push({role:'user',text:q,refs:[]});let answer;if(wf.pending?.session===s.id&&/^(确认|继续|开始|就按这个|是的)[。！!\s]*$/.test(q)){const t=wfCreate(wf.pending.text,'对话',{parent:s.parentTask||(s.report?rcRows.find(r=>r.id===s.report)?.task:null)});wf.pending=null;answer={text:`已建立 ${t.id}。这是本地交互演示，未调用模型或采集。时间范围 ${t.window}，自动选型 ${t.template}，预算上限 ¥${t.budget}；可继续在对话中补充要求。`,task:t.id};}else if(/共创.*模板|模板.*共创/.test(q)){answer={text:'可以在对话中共创模板。请说明报告面向谁、研究哪类主题，以及必须包含哪些章节。我会先整理章节骨架；模板本身不启动采集研究。当前为本地交互演示。'};}else if(wfIntent(q)){if(/^(研究一下|帮我研究|生成报告|给我报告|分析一下|深度研判)[。！!\s]*$/.test(q)){answer={text:'请告诉我需要研究的具体主题，例如“调查近七天 AI 行业争议，给我完整报告”。不需要另填表单。'};}else{const ambiguous=/怎么|如何|能否|是否/.test(q);if(ambiguous){wf.pending={session:s.id,text:q};answer={text:'你是在了解方法，还是希望开始一次新的取证研究？如果希望执行，请回复“开始”并说明主题。'};}else{const t=wfCreate(q,'对话',{parent:s.parentTask||(s.report?rcRows.find(r=>r.id===s.report)?.task:null)});s.task=t.id;answer={text:`已建立独立任务 ${t.id}。采用 ${t.window}，自动选型「${t.template}」，交付完整图文报告与证据附录。默认预算上限 ¥${t.budget}，需要扩大权限时单独处理。当前为本地演示，尚未发起真实调用。`,task:t.id};}}}else if(s.task&&/^(时间|范围|改为|改成|补充|重点|关注|模板|预算)/.test(q)){const t=wfTask(s.task);t.notes.push(q);wfEvent(t,'收到对话补充要求：'+q);answer={text:'补充要求已关联到 '+t.id+'。当前配置快照保留；需要更改执行范围时由任务规划处理，不会覆盖其他任务。',task:t.id};}else answer=wfBasicAnswer(q);s.messages.push({role:'assistant',refs:[],...answer});v4State.estTokens+=Math.ceil((q.length+answer.text.length)/2);v4RenderChat();if(v4State.quick)v4RenderQuick();v4RefreshStreams();};
v4MessageHTML=function(m){return wfOriginalMessageHTML({...m,research:false,deep:false})+(m.task&&wfTask(m.task)?wfChatCard(wfTask(m.task)):'');};
function wfChatCard(t){return `<div class="wf-chat-task"><div class="wf-between"><b>${wfSafe(t.id)}</b>${wfBadge(t.status)}</div><h4>${wfSafe(t.title)}</h4><p>${wfSafe(t.window)} · ${wfSafe(t.template)} · 本地演示</p><div class="wf-actions"><button class="btn" onclick="wfOpenTask('${t.id}')">查看任务</button>${t.status==='运行中'?`<button class="btn" onclick="wfAction('${t.id}','pause')">暂停</button>`:''}${t.report?`<button class="btn" onclick="rcRead('${t.report}')">阅读报告</button>`:''}</div></div>`;}
function wfCompose(context='',parent=null){v4CloseModal();v4NewSession();const s=v4Session();s.title=context?'研究：'+context.slice(0,18):'新的研究对话';if(parent)s.parentTask=parent;v4Go('chat');const input=document.querySelector('#p-chat textarea');if(input){input.value=context?(/模板.*共创|共创.*模板/.test(context)?context:'请研究：'+context+'，给我完整报告。'):'';input.focus();}}
v4DeepRequest=()=>wfCompose();v4StartResearch=()=>wfCompose();
const wfRenderChatOriginal=v4RenderChat;
v4RenderChat=function(){wfRenderChatOriginal();const p=document.getElementById('p-chat');p.querySelector('.topbar button').outerHTML='<button class="btn" style="margin-left:auto" onclick="v4Go(\'tasks\')">研究任务</button>';p.querySelector('.v4-note').textContent='直接提问即可。明确要求研究时建立独立任务；普通问答和报告追问不会自动重复取证。当前为本地规则演示，未连接真实模型。';p.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('查看研判与证据')){b.textContent='查看关联任务与证据';b.onclick=()=>{const s=v4Session();const id=s.task||rcRows.find(r=>r.id===s.report)?.task;if(id)wfOpenTask(id);else v4Go('tasks');};}});};
v4Sessions.find(s=>s.id==='research-help').messages[0].text='直接告诉我研究主题、时间或重点。明确提出研究需求后，会建立独立任务并在这里显示进度；无需再填写表单。';
function wfTaskList(){const rows=wfTasks.filter(t=>(wf.filter==='全部'||t.status===wf.filter||(wf.filter==='待处理'&&['等待审批','待确认','失败','待审核'].includes(t.status)))&&[t.id,t.title,t.source].join(' ').toLowerCase().includes(wf.query.toLowerCase()));document.getElementById('p-tasks').innerHTML=`${wfHead('研究任务','每次研究独立保存；对话、自动监测与定时任务共用队列',`<button class="btn dark" onclick="wfCompose()">去对话提出研究</button>`)}${wfStats()}<div class="wf-note">本地演示 · 一个完整研判执行槽，其余排队；任务内三引擎并行。点击任务查看专属过程。刷新清空本轮操作。</div><div class="wf-panel"><div class="wf-toolbar"><input id="wf-task-search" aria-label="搜索研究任务" placeholder="搜索任务名称或编号" value="${wfSafe(wf.query)}"><select id="wf-task-filter" aria-label="任务状态">${['全部','待处理','待确认','排队中','运行中','等待审批','暂停','待审核','完成','失败','已取消'].map(s=>`<option ${s===wf.filter?'selected':''}>${s}</option>`).join('')}</select></div><div class="v4-scroll-table"><table class="wf-table"><thead><tr><th>研究 / 议题</th><th>来源</th><th>状态 / 阶段</th><th>创建时间</th><th>预算</th><th>操作</th></tr></thead><tbody>${rows.map(t=>`<tr><td><button class="wf-title" onclick="wfOpenTask('${t.id}')">${wfSafe(t.title)}</button><small>${t.id}${t.parent?' · 关联 '+t.parent:''}</small></td><td>${t.source}</td><td>${wfBadge(t.status)}<small>${t.stage<8?wfStages[t.stage]:'已形成报告'}</small></td><td>${t.created}</td><td>上限 ¥${t.budget}<small>实际用量未接入</small></td><td><button class="btn" onclick="wfOpenTask('${t.id}')">查看任务</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="wf-empty">暂无符合条件的任务</div>':''}</div>`;}
function wfHead(title,sub,actions=''){return `<div class="topbar"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="wf-actions" style="margin-left:auto">${actions}</div></div>`;}
function wfStats(){return `<div class="wf-stats">${[['运行中',wfTasks.filter(t=>t.status==='运行中').length,'#486df1'],['排队中',wfTasks.filter(t=>t.status==='排队中').length,'#8260df'],['待处理',wfTasks.filter(t=>['等待审批','待确认','失败','待审核'].includes(t.status)).length,'#d69a25'],['报告成果',rcRows.length,'#19a77f']].map(([label,n,c])=>`<button style="--wf-accent:${c}" onclick="wf.filter='${label==='报告成果'?'全部':label}';v4Go('${label==='报告成果'?'report':'tasks'}')"><span>${label}</span><b>${n}</b></button>`).join('')}</div>`;}
function wfOpenTask(id,tab='过程'){if(!wfTask(id))return;wf.task=id;wf.tab=tab;v4Go('tasks');wfDetail();}
function wfDetail(){const t=wfTask(wf.task);if(!t){wfTaskList();return;}const active=t.status==='运行中';document.getElementById('p-tasks').innerHTML=`<button class="btn" onclick="wf.task=null;wfTaskList()">← 全部研究任务</button>${wfHead(wfSafe(t.title),`${t.id} · ${t.source} · ${t.created}`,`${wfBadge(t.status)}${active?`<button class="btn" onclick="wfAction('${t.id}','pause')">暂停</button>`:''}${['暂停','待确认','失败'].includes(t.status)?`<button class="btn" onclick="wfAction('${t.id}','resume')">${t.status==='失败'?'重试失败阶段':t.status==='待确认'?'启动任务':'继续'}</button>`:''}${t.status==='等待审批'?`<button class="btn" onclick="v4Go('approve')">去审批中心</button>`:''}${!['完成','已取消'].includes(t.status)?`<button class="btn" onclick="wfAction('${t.id}','cancel')">取消任务</button>`:''}`)}<div class="wf-scope"><span>范围 <b>${wfSafe(t.window)}</b></span><span>模板 <b>${wfSafe(t.template)}</b></span><span>预算上限 <b>¥${t.budget}</b></span><span>执行尝试 <b>${t.attempt}</b></span><span>关联研究 <b>${t.parent||'无'}</b></span></div><div class="wf-tabs">${['过程','资料与证据','成员与讨论','消费与日志','报告产物'].map(tab=>`<button class="${wf.tab===tab?'on':''}" onclick="wf.tab='${tab}';wfDetail()">${tab}</button>`).join('')}</div>${wfTaskBody(t)}<div class="wf-note">任务数据按编号隔离。当前仅演示产品流程，未真实调用 dsh、BettaFish、采集工具或通知渠道。</div>`;}
function wfTaskBody(t){if(wf.tab==='过程')return `<div class="wf-grid"><div class="wf-panel"><h3>研判工作台 · 本任务过程</h3><div class="wf-stages">${wfStages.map((s,i)=>`<div class="${i<t.stage?'done':i===t.stage?'current':''}"><span>${i<t.stage?'✓':i+1}</span><div><b>${s}</b><small>${i<t.stage?'演示阶段已结束':i===t.stage?t.status==='运行中'?'当前演示阶段':t.status:'尚未调度'}</small></div></div>`).join('')}</div>${t.status==='运行中'?`<div class="wf-demo-controls"><b>体验流程</b><p>手动推进用于检查页面流转，不代表真实取证或质量审查通过。</p><button class="btn dark" onclick="wfAdvance('${t.id}')">演示推进下一阶段</button><button class="btn" onclick="wfAction('${t.id}','fail')">演示阶段失败</button></div>`:''}</div><div><div class="wf-panel"><h3>研究要求</h3><p>完整报告、统计底表、图表、来源附录；缺失不补造。保留三引擎、Forum、三道审查和 ReportEngine。</p>${t.notes.map(x=>`<p>${wfSafe(x)}</p>`).join('')}<button class="btn" onclick="wfSupplement('${t.id}')">补充线索或要求</button></div><div class="wf-panel"><h3>任务记录</h3>${wfLogs(t.events.slice(-6))}</div></div></div>`;
 if(wf.tab==='资料与证据')return `<div class="wf-panel"><div class="wf-between"><h3>任务专属资料与证据 · ${t.evidence.length} 项</h3><button class="btn" onclick="wf.recordTask='${t.id}';v4Go('crawl')">查看本任务采集记录</button></div>${t.evidence.length?t.evidence.map(e=>`<div class="wf-evidence"><b>${wfSafe(e.id)} · ${wfSafe(e.title)}</b><small>${wfSafe(e.source)}</small><blockquote>${wfSafe(e.quote)}</blockquote><span>演示片段，非实际调查证据</span><button class="btn" onclick="wfEvidence('${t.id}','${e.id}')">查看任务证据</button></div>`).join(''):'<div class="wf-empty">尚无真实归档资料。模拟运行不会填入虚构证据或数字。</div>'}${t.claims.length?'<h3>结论与依据</h3>'+t.claims.map(c=>'<p><b>'+wfSafe(c.id)+'</b> '+wfSafe(c.title)+' <span class="v4-label">'+wfSafe((c.refs||[]).join(' · '))+'</span></p>').join(''):''}<button class="btn" onclick="wfSupplement('${t.id}')">添加材料线索</button></div>`;
 if(wf.tab==='成员与讨论')return `<div class="wf-panel"><h3>本任务成员与门禁</h3><div class="wf-member-grid">${[['planner','证据充分性与任务拆解'],['Insight','库内检索、统计和反思'],['Media','外网、多模态资料与反思'],['Query','新闻研究与反思'],['ForumHost','多轮主持、反馈补证'],['verifier','原文核实与数据核对'],['advocate','反证、替代解释与局限'],['Report','六模板、逐章成稿、IR、图表和导出']].map(([n,d])=>`<div><b>${n}</b><p>${d}</p><small>成员消息由真实执行器接入后显示</small></div>`).join('')}</div><h3>Forum 讨论</h3><div class="wf-empty">当前没有真实成员发言，不伪造会议内容。任务范围、证据和讨论按 ${t.id} 隔离。</div></div>`;
 if(wf.tab==='消费与日志')return `<div class="wf-grid"><div class="wf-panel"><h3>本任务消费</h3><p>预算上限 ¥${t.budget}；实际 usage 未接入。</p><p>输入、输出、缓存和外部调用分开记录。未知费用不计为免费。</p><details><summary>启动时的配置快照</summary><pre>${wfSafe(JSON.stringify(t.config,null,2))}</pre></details><button class="btn" onclick="v4Go('usage')">全平台演示账本</button></div><div class="wf-panel"><h3>执行日志 · attempt ${t.attempt}</h3>${wfLogs(t.events)}</div></div>`;
 return `<div class="wf-panel"><h3>报告与版本</h3>${t.report?`<p>${wfSafe(rcRows.find(r=>r.id===t.report)?.title||t.title)} · ${rcRows.find(r=>r.id===t.report)?.version||'v1'}</p><button class="btn dark" onclick="rcRead('${t.report}')">阅读报告</button><button class="btn" onclick="v4AskReport('${t.report}')">追问报告</button><button class="btn" onclick="wfCompose('更新研究：'+wfTask('${t.id}').title,'${t.id}')">更新研究</button>`:'<div class="wf-empty">尚未形成报告。执行过程在本任务中保留，不生成空报告占位。</div>'}</div>`;
}
function wfLogs(rows){return rows.map(e=>`<div class="wf-log"><time>${wfSafe(e.time)}</time><p>${wfSafe(e.text)}</p></div>`).join('');}
function wfEvidence(task,id){const e=wfTask(task)?.evidence.find(x=>x.id===id);if(!e)return;v4Modal(task+' / '+id,`<h3>${wfSafe(e.title)}</h3><p>${wfSafe(e.source)}</p><blockquote class="wf-note">${wfSafe(e.quote)}</blockquote><p class="v4-label">仅展示该任务的演示材料，不跨任务补造引用。</p>`);}
function wfAction(id,action){const t=wfTask(id);if(!t)return;if(action==='pause'&&t.status==='运行中'){t.status='暂停';wfEvent(t,'暂停后续调度；真实系统中已发请求仍可能完成并计费。');}else if(action==='resume'&&['暂停','待确认','失败'].includes(t.status)){if(t.status==='失败')t.attempt++;t.status='排队中';wfEvent(t,'从当前检查点重新排队，不覆盖此前尝试。');}else if(action==='cancel'&&!['完成','已取消'].includes(t.status)){t.status='已取消';wfEvent(t,'取消后续执行，保留已取得资料与日志。');}else if(action==='fail'&&t.status==='运行中'){t.status='失败';wfEvent(t,'演示失败：真实系统会在重试耗尽后通知。');wfNote('failure',t,'任务失败，需要处理');}else return;wfDispatch();wfRefresh();v4RefreshStreams();}
function wfAdvance(id){const t=wfTask(id);if(t?.status!=='运行中')return;wfEvent(t,'演示结束阶段：'+wfStages[t.stage]+'；未执行真实检索或审查。');if(t.stage===1)wf.records.unshift({id:'FETCH-'+id,time:wfNow(),task:id,source:'search',operation:'三引擎取数',status:'模拟记录',detail:'未实际发起请求；真实结果数量未知。'});t.stage++;if(t.stage===8){t.status='完成';const rid='report-'+id;t.report=rid;const version=wfTasks.filter(x=>x.parent===t.parent&&x.report&&t.parent).length+1;rcRows.unshift({id:rid,title:t.title,type:'专题研究',status:'可交付',date:wfNow(),topic:t.title.slice(0,20),task:id,version:'v'+version,desc:'流程演示产物：无真实数据，不能作为正式研究报告。',demoTask:true});v4Reports[rid]={title:t.title,desc:'本地流程样例，没有真实调查证据。',kind:'流程演示'};wfEvent(t,'演示成品已入本页目录；没有生成真实数据报告。');wfNote('complete',t,'演示报告已形成，真实通知未发送');wfDispatch();}wfRefresh();v4RefreshStreams();}
function wfSupplement(id){v4Modal('补充本任务线索',`<form id="wf-supplement" data-task="${id}"><label for="wf-material">材料链接或研究要求</label><textarea id="wf-material" name="text" required placeholder="填写链接或补充说明"></textarea><p class="v4-label">仅保存任务备注，不会因为填写链接就宣称已抓取归档。</p><button class="btn dark">保存到 ${id}</button></form>`);}
function wfSyncSignals(){for(const s of wf.signals){if(s.status==='已忽略'||!s.task)continue;const t=wfTask(s.task);if(t)s.status=({'完成':'已完成','运行中':'研究中','暂停':'已暂停','失败':'待处理'})[t.status]||t.status;}}
function wfRefresh(){wfSyncSignals();if(wf.page==='tasks')wf.task?wfDetail():wfTaskList();if(wf.page==='dash')wfDashboard();if(wf.page==='hot')wfHotRender();if(wf.page==='approve')wfApprovals();if(wf.page==='crawl')wfRecords();}
const wfOriginalDashboard=document.getElementById('p-dash').innerHTML;
function wfDashboardAdditions(){return `<div class="wf-grid"><div class="wf-panel"><div class="wf-between"><h3>待你处理</h3><button class="wf-link" onclick="v4Go('tasks')">全部任务 ↗</button></div>${wfTasks.filter(t=>['等待审批','待确认','失败','待审核'].includes(t.status)).slice(0,4).map(t=>`<button class="wf-list-item" onclick="wfOpenTask('${t.id}')"><span><b>${wfSafe(t.title)}</b><small>${t.id} · ${t.status==='待审核'?'统计口径与证据仍需核对':'需要处理后才能继续'}</small></span>${wfBadge(t.status)}</button>`).join('')}</div><div class="wf-panel"><div class="wf-between"><h3>重点预警</h3><button class="wf-link" onclick="wfHotTab('预警线索')">查看线索 ↗</button></div>${wf.signals.filter(s=>s.status!=='已忽略').slice(0,3).map(s=>`<button class="wf-list-item" onclick="wfSignal('${s.id}')"><span><b>${wfSafe(s.title)}</b><small>示例预警 · ${s.task?'已有任务 '+s.task:'尚未启动研究'}</small></span>${wfBadge(s.status)}</button>`).join('')}</div><div class="wf-panel"><h3>运行与排队</h3>${wfTasks.filter(t=>['运行中','排队中'].includes(t.status)).map(t=>`<button class="wf-list-item" onclick="wfOpenTask('${t.id}')"><span><b>${wfSafe(t.title)}</b><small>${t.id} · ${wfStages[t.stage]}</small></span>${wfBadge(t.status)}</button>`).join('')}</div><div class="wf-panel"><div class="wf-between"><h3>最新报告</h3><button class="wf-link" onclick="v4Go('report')">报告中心 ↗</button></div>${rcRows.slice(0,3).map(r=>`<button class="wf-list-item" onclick="rcRead('${r.id}')"><span><b>${wfSafe(r.title)}</b><small>${r.date} · ${r.version}</small></span>${wfBadge(r.status)}</button>`).join('')}</div></div>`;}
function wfDashboard(){const page=document.getElementById('p-dash');page.innerHTML=wfOriginalDashboard;v4UpdateDashboard();const create=page.querySelector('.topbar .newtask');if(create){create.textContent='＋ 新建研究';create.onclick=()=>wfCompose();}page.querySelectorAll('.phead').forEach(head=>{const title=head.querySelector('h3')?.textContent||'';const link=head.querySelector('.right');if(!link)return;if(title.includes('信号')){link.onclick=()=>v4Go('sigs');link.style.cursor='pointer';}else if(title.includes('活动流')||title.includes('热度')){link.textContent=link.textContent.replace('查看议题','查看研究任务');link.onclick=()=>v4Go('tasks');link.style.cursor='pointer';}});page.insertAdjacentHTML('beforeend','<section id="wf-dashboard-additions">'+wfDashboardAdditions()+'</section>');}

// Keep the original hotlist cards, replace duplicated daily/RSS/config surfaces.
const wfHotPage=document.getElementById('p-hot');
const wfHotView=document.getElementById('hot-view');
const wfHotCards=wfHotView.cloneNode(true);
wfHotCards.querySelector(':scope > .panel')?.remove();
wfHotPage.innerHTML=wfHead('热点追踪','发现热点、处理预警、配置监测；日报成品统一在报告中心',`<button class="btn" onclick="v4Go('report')">查看日报与报告</button>`)+`<div class="wf-tabs" id="wf-hot-tabs"></div><div id="wf-hot-body"></div>`;
function wfHotTab(tab){wf.hot=tab;v4Go('hot');}
function wfHotRender(){document.getElementById('wf-hot-tabs').innerHTML=['榜单','预警线索','监测订阅'].map(tab=>`<button class="${wf.hot===tab?'on':''}" onclick="wfHotTab('${tab}')">${tab}</button>`).join('');const host=document.getElementById('wf-hot-body');if(wf.hot==='榜单'){host.innerHTML='<div class="wf-note">以下沿用原版榜单演示数据。刷新仅执行采集演示，不启动研究，也不代表已连接线上平台。</div><div class="wf-actions"><button class="btn" onclick="wfPoll()">演示刷新热点</button><button class="btn" onclick="wfHotTab(\'监测订阅\')">管理监测频率与触发策略</button></div>';host.append(wfHotCards);wfHotCards.style.display='block';wfHotCards.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('暂停刷新')){b.textContent='自动监测设置';b.onclick=()=>wfHotTab('监测订阅');}});return;}
 if(wf.hot==='预警线索'){host.innerHTML=`<div class="wf-note">命中规则形成线索；线索不等于核实结论。发起研究会进入对话，自动研判仅按已配置策略创建任务。</div>${wf.signals.map(s=>`<div class="wf-panel"><div class="wf-between"><h3>${wfSafe(s.title)}</h3>${wfBadge(s.status)}</div><p>${wfSafe(s.reason)}</p><small>${s.id} · ${wfSafe(wf.monitors.find(m=>m.id===s.monitor)?.name||'监测规则')}</small><div class="wf-actions"><button class="btn" onclick="wfSignal('${s.id}')">查看依据与处理</button>${s.task?`<button class="btn" onclick="wfOpenTask('${s.task}')">查看 ${s.task}</button>`:`<button class="btn" onclick="wfResearchSignal('${s.id}')">对话发起研究</button>`}</div></div>`).join('')}`;return;}
 host.innerHTML=`<div class="wf-between"><div><h3>监测订阅</h3><p class="v4-label">品牌监测也是一种订阅。采集频率、命中策略和通知对象在此管理。</p></div><button class="btn dark" onclick="wfMonitorForm()">＋ 新建订阅</button></div>${wf.monitors.map(m=>`<div class="wf-panel"><div class="wf-between"><h3>${wfSafe(m.name)}</h3>${wfBadge(m.enabled?'已开启':'已暂停')}</div><p>关键词：${wfSafe(m.keywords)}</p><div class="wf-scope"><span>${wfSafe(m.frequency)}${m.cron?' · '+wfSafe(m.cron):''}</span><span>${m.strategy}</span><span>通知：${m.channel}</span></div><div class="wf-actions"><button class="btn" onclick="wfMonitorForm('${m.id}')">编辑规则</button><button class="btn" onclick="wfToggleMonitor('${m.id}')">${m.enabled?'暂停':'开启'}</button><button class="btn" ${m.enabled?'':'disabled'} onclick="wfTrigger('${m.id}')">演示一次命中</button></div></div>`).join('')}<div class="wf-note">当前不会定时联网。演示命中会验证去重和任务流转；通知只写入本页记录，不向飞书或企业微信发送。</div>`;}
function wfPoll(){wf.records.unshift({id:'POLL-'+Date.now(),time:wfNow(),task:null,source:'newsnow',operation:'热榜快照',status:'模拟记录',detail:'仅演示调度，未请求线上服务。'});showToast('已记录一次模拟采集；未启动研究任务');}
function wfToggleMonitor(id){const m=wf.monitors.find(x=>x.id===id);m.enabled=!m.enabled;wfHotRender();}
function wfMonitorForm(id){const m=wf.monitors.find(x=>x.id===id)||{name:'',keywords:'',frequency:'15 分钟',strategy:'创建待确认任务',channel:'仅平台内'};v4Modal(id?'编辑监测订阅':'新建监测订阅',`<form id="wf-monitor-form" data-id="${id||''}"><div class="v4-field"><label for="wf-monitor-name">订阅名称</label><input id="wf-monitor-name" name="name" required value="${wfSafe(m.name)}"></div><div class="v4-field"><label for="wf-monitor-keys">关键词 / 品牌与别名</label><input id="wf-monitor-keys" name="keywords" required value="${wfSafe(m.keywords)}"></div><div class="v4-field"><label>检查频率</label><select name="frequency">${['5 分钟','15 分钟','30 分钟','60 分钟','自定义 cron'].map(x=>`<option ${x===m.frequency?'selected':''}>${x}</option>`).join('')}</select></div><div class="v4-field"><label>自定义 cron（五段表达式）</label><input name="cron" placeholder="例如：*/15 * * * *" value="${wfSafe(m.cron||'')}"></div><div class="v4-field"><label>命中后的处理</label><select name="strategy">${['仅提醒','创建待确认任务','自动研判'].map(x=>`<option ${x===m.strategy?'selected':''}>${x}</option>`).join('')}</select></div><div class="v4-field"><label>通知渠道</label><select name="channel">${['仅平台内','飞书','企业微信'].map(x=>`<option ${x===m.channel?'selected':''}>${x}</option>`).join('')}</select></div><div class="wf-note">默认演示命中条件为关键词匹配并满足观察窗口。真实升温阈值、最小基数与采集覆盖需后端规则接入；自动研究默认每日最多 2 次，每次预算 ¥20。这里保存的是本页策略草稿。</div><button class="btn dark">保存订阅草稿</button></form>`);}
function wfTrigger(id){const m=wf.monitors.find(x=>x.id===id);if(!m?.enabled)return;let s=wf.signals.find(x=>x.monitor===id&&x.status!=='已忽略');if(!s){s={id:'SIG-'+Date.now(),title:m.name+'新线索',monitor:id,status:'待关注',task:null,reason:'手动演示命中，不是线上异常检测结果。'};wf.signals.unshift(s);}if(s.task){showToast('已有任务 '+s.task+'，本次合并线索，不重复创建');return;}if(m.strategy==='自动研判'&&wfTasks.filter(t=>t.monitor===id&&t.created.slice(0,10)===wfNow().slice(0,10)).length>=2){showToast('已达到本订阅每日自动研究上限，保留线索等待人工处理');wfHotRender();return;}if(m.strategy!=='仅提醒'){const t=wfCreate(s.title,'热点自动触发',{draft:m.strategy==='创建待确认任务',channel:m.channel});t.monitor=id;s.task=t.id;s.status=m.strategy==='自动研判'?'研究中':'待确认';wfNote('accepted',t,'监测线索已创建任务');}wf.notifications.unshift({key:'signal:'+s.id,task:s.task,title:s.title,channel:m.channel,time:wfNow(),status:'待接入 · 未发送'});wfHotRender();showToast(m.strategy==='仅提醒'?'已记录演示预警，未启动研究':'任务已关联；自动任务不会覆盖对话任务');}
function wfSignal(id){const s=wf.signals.find(x=>x.id===id);v4Modal('预警线索详情',`<h3>${wfSafe(s.title)}</h3><p>${wfSafe(s.reason)}</p><div class="wf-note">这是界面示例，没有实际原文或统计底表，不能视为已核实风险。生产信号须带触发规则、源覆盖、证据和时间窗。</div><div class="wf-actions">${s.task?`<button class="btn dark" onclick="v4CloseModal();wfOpenTask('${s.task}')">查看关联任务 ${s.task}</button>`:`<button class="btn dark" onclick="wfResearchSignal('${s.id}')">在对话中研究</button>`}<button class="btn" onclick="wfIgnore('${s.id}')">标记忽略</button><button class="btn" onclick="wfAssociate('${s.id}')">关联已有任务</button></div>`);}
function wfIgnore(id){wf.signals.find(x=>x.id===id).status='已忽略';v4CloseModal();wfRefresh();}
function wfResearchSignal(id){const s=wf.signals.find(x=>x.id===id);wfCompose(s.title);v4Session().signal=id;}
function wfAssociate(id){v4Modal('关联已有任务',wfTasks.filter(t=>!['已取消','完成'].includes(t.status)).map(t=>`<button class="wf-list-item" onclick="wfLink('${id}','${t.id}')"><span>${wfSafe(t.title)}<small>${t.id}</small></span>${wfBadge(t.status)}</button>`).join(''));}
function wfLink(sid,tid){const s=wf.signals.find(x=>x.id===sid);s.task=tid;s.status='研究中';wfEvent(wfTask(tid),'关联预警线索 '+sid);v4CloseModal();wfRefresh();}
function wfSources(){document.getElementById('p-src').innerHTML=`${wfHead('信源 · 数据源与连接','已接入的取数渠道与能力；具体文章和帖子在任务资料中查看',`<button class="btn" onclick="v4Go('keys')">配置服务与凭据</button>`)}<div class="wf-note">渠道配置后即可出现在这里；只有真实测试或调用后才能显示健康结果。当前各渠道均未实测。</div><div class="wf-panel"><div class="v4-scroll-table"><table class="wf-table"><thead><tr><th>渠道</th><th>类别</th><th>能力</th><th>健康 / 最近成功</th><th>操作</th></tr></thead><tbody>${wf.sources.map(([id,name,type,cap])=>`<tr><td><b>${name}</b></td><td>${type}</td><td>${cap}</td><td>${wfBadge('未实测')}<small>最近成功：未知</small></td><td><button class="btn" onclick="wf.recordSource='${id}';wf.recordTask=null;v4Go('crawl')">查看采集记录</button></td></tr>`).join('')}</tbody></table></div></div><div class="wf-note">检索服务负责发现链接，抓取工具负责获取内容，原文发布平台才是内容来源。搜索结果不等于正文，也不等于可用证据。</div>`;}
function wfRecords(){let rows=wf.records.filter(r=>(!wf.recordTask||r.task===wf.recordTask)&&(!wf.recordSource||r.source===wf.recordSource));document.getElementById('p-crawl').innerHTML=`${wfHead('采集流水 · 采集记录','同一份执行记录，支持全平台和任务视角查看',`<button class="btn" onclick="wf.recordTask=null;wf.recordSource=null;wfRecords()">查看全部记录</button>`)}<div class="wf-note">${wf.recordTask?'当前任务 '+wf.recordTask+' · ':''}${wf.recordSource?'当前渠道 '+wf.recordSource+' · ':''}真实获取或失败时才生成执行记录；阅读报告、普通问答不触发采集。当前模拟记录与真实执行明确区分。</div><div class="wf-panel"><div class="v4-scroll-table"><table class="wf-table"><thead><tr><th>时间 / 编号</th><th>来源</th><th>关联任务</th><th>操作</th><th>结果</th><th>说明</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.time}<small>${r.id}</small></td><td>${r.source}</td><td>${r.task?`<button class="wf-link" onclick="wfOpenTask('${r.task}')">${r.task}</button>`:'监测采集'}</td><td>${r.operation}</td><td>${wfBadge(r.status)}</td><td>${r.detail}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="wf-empty">尚无符合条件的执行记录。配置好信源并不代表已经取过数据。</div>':''}</div>`;}
function wfApprovals(){document.getElementById('p-approve').innerHTML=`${wfHead('审批中心','仅对具体操作授权；普通研究不重复弹整张表单')}<div class="wf-note">这是本地审批演示，不会实际扩大系统权限或执行采集。正式系统需校验审批人与授权范围。</div>${wfTasks.filter(t=>t.status==='等待审批').map(t=>`<div class="wf-panel"><h3>${wfSafe(t.title)}</h3><p>${t.id} · 示例：扩大登录态平台的评论采集范围。</p><div class="wf-actions"><button class="btn" onclick="wfApprove('${t.id}',true)">演示批准并入队</button><button class="btn" onclick="wfApprove('${t.id}',false)">演示拒绝</button><button class="btn" onclick="wfOpenTask('${t.id}')">查看任务</button></div></div>`).join('')||'<div class="wf-empty">没有待审批操作</div>'}`;}
function wfApprove(id,ok){const t=wfTask(id);if(t.status!=='等待审批')return;t.status=ok?'排队中':'已取消';wfEvent(t,ok?'本地审批演示通过，重新入队；未执行实际授权操作。':'本地审批演示拒绝。');wfDispatch();wfApprovals();}
function wfNotifications(){v4Modal('通知规则与发送记录',`<form id="wf-notify-form"><div class="v4-field"><label>默认任务通知渠道</label><select name="channel">${['仅平台内','飞书','企业微信'].map(c=>`<option ${wf.notify.channel===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="v4-field"><label>默认研究预算上限（元）</label><input name="taskBudget" type="number" min="1" max="1000" step="0.01" required value="${wf.defaults.budget}"></div><p>信号生成或升级、等待审批、预算告警、重试后失败、报告入库成功时触发。普通采集成功和成员发言不即时通知。</p><div class="wf-note">静默时段 ${wf.notify.quiet}，预算告警 ${wf.notify.budget}%（配置示例）。真实调度与静默策略尚未接入。通知失败不改变任务或报告完成状态。</div><button class="btn dark">保存本页默认渠道</button></form><h3>本页事件记录</h3>${wf.notifications.length?wf.notifications.map(n=>`<div class="wf-log"><time>${n.time} · ${n.channel}</time><p>${wfSafe(n.title)} · ${n.status}</p></div>`).join(''):'<p class="v4-label">暂无事件；未实际发送消息。</p>'}`);}
// Tie every report to its own task and immutable report version.
rcTask=function(id){const r=rcRows.find(x=>x.id===id);if(r)wfOpenTask(r.task);};
rcUpdate=function(id){const r=rcRows.find(x=>x.id===id);wfCompose('更新研究：'+r.title,r.task);};
const wfOldBody=rcBody;rcBody=function(r){return r.demoTask?`<h2>流程演示报告</h2><p>本产物来自 ${r.task} 的本地阶段推进，未进行真实调查，不能作为事实报告。</p><h2>数据与证据缺口</h2><table><tr><th>项目</th><th>当前结果</th></tr><tr><td>采集样本与统计底表</td><td>未接入</td></tr><tr><td>来源核实与图表</td><td>缺少真实输入，不生成数字与曲线</td></tr></table><h2>下一步</h2><p>接入采集、归档、代码统计、质量审查和 ReportEngine 后，才能交付带真实证据与底表的完整报告。</p>`:wfOldBody(r);};
const wfOldRead=rcRead;rcRead=function(id){wfOldRead(id);wf.page='report';};
const wfOldGo=v4Go;
v4Go=function(id){wfSyncSignals();if(id==='topics'||id==='research')id='tasks';if(id==='deepreport'){wfStandards();return;}if(id==='brand'){wf.hot='监测订阅';id='hot';}wf.page=id;if(id==='tasks'){showPage('tasks');document.querySelector('aside a[data-p="tasks"]')?.classList.add('on');wf.task?wfDetail():wfTaskList();return;}wfOldGo(id);if(id==='dash')wfDashboard();if(id==='hot')wfHotRender();if(id==='src')wfSources();if(id==='crawl')wfRecords();if(id==='approve')wfApprovals();if(id==='logs')wfRunLogs();};
function wfRunLogs(){document.getElementById('p-logs').innerHTML=wfHead('运行日志','任务、采集和通知事件可回溯；不保存密钥',`<button class="btn" onclick="wfNotifications()">通知记录</button>`)+`<div class="wf-panel">${wfLogs(wfTasks.flatMap(t=>t.events.map(e=>({...e,text:t.id+' · '+e.text}))).sort((a,b)=>b.time.localeCompare(a.time)))}</div>`;}
function wfStandards(){v4Modal('完整报告交付标准',`<p>保留三引擎、Forum、多轮反思、六模板、逐章生成、IR、图表表格校验和 HTML / MD / PDF。</p><table><thead><tr><th>章节</th><th>数据前提</th></tr></thead><tbody>${v4ReportSections.map(([n,t,d,r])=>`<tr><td>${n} ${t}</td><td>${r}</td></tr>`).join('')}</tbody></table><button class="btn" onclick="v4DataContract()">查看统计底表要求</button>`);}
document.addEventListener('click',e=>{const a=e.target.closest('aside a[data-p]');if(!a)return;e.preventDefault();e.stopImmediatePropagation();if(a.dataset.p==='tasks'){wf.task=null;wf.filter='全部';}v4Go(a.dataset.p);},true);
document.addEventListener('input',e=>{if(e.target.id==='wf-task-search'){const pos=e.target.selectionStart;wf.query=e.target.value;wfTaskList();const input=document.getElementById('wf-task-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='wf-task-filter'){wf.filter=e.target.value;wfTaskList();}});
document.addEventListener('submit',e=>{if(e.target.id==='wf-monitor-form'){e.preventDefault();const d=new FormData(e.target);if(d.get('frequency')==='自定义 cron'&&String(d.get('cron')).trim().split(/\s+/).length!==5){showToast('请输入五段 cron 表达式；当前仅保存配置，不运行调度');return;}let m=wf.monitors.find(x=>x.id===e.target.dataset.id);if(!m){m={id:'MON-'+Date.now(),enabled:true};wf.monitors.push(m);}for(const key of ['name','keywords','frequency','strategy','channel','cron'])m[key]=String(d.get(key)).trim();v4CloseModal();wfHotTab('监测订阅');}if(e.target.id==='wf-supplement'){e.preventDefault();const t=wfTask(e.target.dataset.task);const text=String(new FormData(e.target).get('text')).trim();if(!text)return;t.notes.push(text);wfEvent(t,'补充材料线索：'+text);v4CloseModal();wfRefresh();}if(e.target.id==='wf-notify-form'){e.preventDefault();const nd=new FormData(e.target);wf.notify.channel=String(nd.get('channel'));wf.defaults.budget=Number(nd.get('taskBudget'));v4CloseModal();showToast('本页默认渠道已保存，未发送消息');}});
// Build the final navigation. Source and collection pages deliberately stay first-level.
const wfNav=document.querySelector('aside #nav')||document.querySelector('aside nav');
wfNav.innerHTML=[['dash','◈','仪表盘'],['hot','♨','热点追踪'],['chat','◌','对话'],['tasks','▤','研究任务'],['sigs','◇','信号'],['src','◎','信源'],['crawl','⇄','采集流水'],['report','▣','报告中心'],['tpl','▧','模板中心']].map(([id,icon,t])=>`<a data-p="${id}" role="button" tabindex="0"><span class="ic">${icon}</span>${t}</a>`).join('');
document.querySelectorAll('aside a[data-p]').forEach(a=>{if(!['dash','hot','chat','tasks','sigs','src','crawl','report','tpl','custom'].includes(a.dataset.p))a.remove();});
document.querySelector('aside .logo small').textContent='舆情研判 AGENT · 对话驱动 v5';
document.querySelector('.v4-status-strip').innerHTML='<span class="v4-badge">对话驱动原型 v5</span><span>本地演示 · 未连接真实引擎 · 本轮操作刷新重置</span><button class="btn" onclick="v4Go(\'chat\')">打开对话</button>';
document.getElementById('p-research').remove();document.getElementById('p-deepreport').remove();
const taskSection=document.createElement('section');taskSection.id='p-tasks';taskSection.className='page';document.querySelector('main.main').append(taskSection);
// Refresh the original static pages list after adding the task route.
showPage=function(id){document.querySelectorAll('main.main > section.page').forEach(p=>p.classList.remove('on'));document.querySelectorAll('aside a[data-p]').forEach(a=>a.classList.toggle('on',a.dataset.p===id));document.getElementById('p-'+id)?.classList.add('on');window.scrollTo(0,0);};
document.getElementById('p-conf').insertAdjacentHTML('afterbegin','<div class="wf-panel"><div class="wf-between"><div><h3>通知与调度</h3><p class="v4-label">一个完整研究执行槽；用户任务优先于未开始的自动任务。通知在信号、审批、失败与报告入库等节点触发。</p></div><button class="btn" onclick="wfNotifications()">通知规则与记录</button></div></div>');
v4KeyMeta.push(['wecom','企业微信通知','Webhook / 签名凭据','#18a678']);
// Template setup stays in its library; co-creation happens in conversation.
const wfTemplatePage=document.getElementById('p-tpl');
wfTemplatePage.querySelectorAll('.topbar button').forEach(b=>{if(b.textContent.includes('共创'))b.onclick=()=>wfCompose('请帮我共创一套报告模板');if(b.textContent.includes('上传'))b.onclick=()=>document.getElementById('wf-template-file').click();});
wfTemplatePage.insertAdjacentHTML('beforeend','<input id="wf-template-file" type="file" accept=".md,text/markdown" hidden><div class="wf-panel" id="wf-uploaded-templates"><h3>本页上传的模板</h3><p class="v4-label">支持 Markdown，最大 1 MB；只保留本页，不上传。内置六模板和原版预览入口继续保留。</p><div id="wf-template-list"></div></div>');
document.getElementById('wf-template-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.md')||file.size>1024*1024){showToast('请选择不超过 1 MB 的 Markdown 文件');e.target.value='';return;}const content=await file.text();const row=document.createElement('div');row.className='wf-list-item';const label=document.createElement('span');label.textContent=file.name;const preview=document.createElement('button');preview.className='btn';preview.textContent='预览';preview.onclick=()=>v4Modal('上传模板 · '+file.name,'<pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+wfSafe(content)+'</pre>');row.append(label,preview);document.getElementById('wf-template-list').append(row);e.target.value='';});
v4AttachReport=function(){v4Modal('选择对话关联的报告',Object.entries(v4Reports).map(([id,r])=>`<button class="v4-session" onclick="v4CloseModal();v4AskReport('${id}')"><strong>${wfSafe(r.title)}</strong><small>${wfSafe(r.kind)} · ${wfSafe(r.desc)}</small></button>`).join(''));};
document.title='谛听 DiTing · 对话驱动控制台 v5';
v4State.session='general';wfHotRender();v4RenderChat();v4Go('dash');
